    and order_no = #{orderNo}
    and user_id = #{userId}
    and job_id = #{jobId}
    and status = #{status}

order by create_time desc

select coalesce(ui.id, 0) as user_info_id, jso.user_id, case when up.real_name is not null and up.real_name != '' then up.real_name when up.nick_name is not null and up.nick_name != '' then up.nick_name when ui.user_name is not null and ui.user_name != '' then ui.user_name else '未注册用户' end as display_name, case when ui.phone is null or ui.phone = '' then '' when char_length(ui.phone) < 7 then ui.phone else concat(left(ui.phone, 3), '****', right(ui.phone, 4)) end as phone_masked, jso.order_no, case when sir.id is null then 0 else sir.sign_status end as attendance_status, case when sir.id is null then '未签到' when sir.sign_status = 1 then '已签到' when sir.sign_status = 2 then '迟到' when sir.sign_status = 3 then '已取消' else '未签到' end as attendance_status_label, sir.sign_time, case when sir.id is null then 0 else 1 end as signed_count, sir.sign_image_url, case when sir.id is null then 0 else ifnull(sir.audit_status, 0) end as audit_status, case when sir.id is null or ifnull(sir.audit_status, 0) = 0 then '未提交' when sir.audit_status = 1 then '待审核' when sir.audit_status = 2 then '已通过' when sir.audit_status = 3 then '已驳回' else '未提交' end as audit_status_label, sir.audit_remark, sir.submit_time from job_signup_order jso left join user_info ui on ui.user_id = jso.user_id left join wx_user_profile up on up.uid = ui.id left join sign_in_record sir on sir.job_order_id = jso.id and sir.record_type = 3 where jso.job_id = #{jobId} and jso.status = #{paidStatus}
and ( ui.user_name like concat('%', #{keyword}, '%') or ui.phone like concat('%', #{keyword}, '%') or up.real_name like concat('%', #{keyword}, '%') or up.nick_name like concat('%', #{keyword}, '%') )
order by ui.id desc, jso.id desc


where user_id = #{userId}
  and job_id = #{jobId}
  and status = 1
order by pay_time desc, id desc
limit 1


where user_id = #{userId}
  and job_id = #{jobId}
  and status = 0
order by create_time desc, id desc
limit 1

