user_id = #{userId}, job_id = #{jobId}, amount = #{amount}, status = #{status}, wechat_transaction_id = #{wechatTransactionId}, refund_no = #{refundNo}, pay_time = #{payTime}, refund_time = #{refundTime}, request_id = #{requestId}, update_time = #{updateTime},
where id = #{id}
